def solve(nums):
    if not nums:
        return 0

    num_set = set(nums)
    max_length = 0

    for num in num_set:
        if num - 1 not in num_set:
            current_length = 1
            current_num = num + 1
            while current_num in num_set:
                current_length += 1
                current_num += 1
            max_length = max(max_length, current_length)

    return max_length
```

