def solve(intervals):
    if not intervals:
        return 0

    # Separate the start and end times
    start = sorted(interval[0] for interval in intervals)
    end = sorted(interval[1] for interval in intervals)

    rooms = 0
    max_rooms = 0
    i = j = 0

    while i < len(intervals):
        if start[i] < end[j]:
            rooms += 1
            i += 1
        else:
            rooms -= 1
            j += 1
        max_rooms = max(max_rooms, rooms)

    return max_rooms
