import re

def solve(nums):
    if not nums:
        return 0
    n = len(nums)
    seen = set()
    max_len = 0
    for i in range(n):
        if nums[i] in seen:
            continue
        seen.add(nums[i])
        current = nums[i]
        count = 1
        for j in range(i + 1, n):
            if nums[j] == current + 1:
                count += 1
                current = nums[j]
            else:
                break
        max_len = max(max_len, count)
    return max_len
