def solve(nums):
    if not nums:
        return 0

    value_to_index = {}
    for i, num in enumerate(nums):
        value_to_index[num] = i

    used = [False] * len(nums)
    max_run = 0

    for i in range(len(nums)):
        if used[i]:
            continue

        current = nums[i]
        run_length = 0
        current_value = current
        current_index = i

        while True:
            if current_index < 0 or current_index >= len(nums) or used[current_index]:
                break
            used[current_index] = True
            run_length += 1
            current_index = value_to_index.get(current_value + 1, -1)
            current_value += 1

        max_run = max(max_run, run_length)

    return max_run
