def solve(nums):
    if not nums:
        return 0

    from collections import defaultdict

    value_to_index = defaultdict(list)
    for i, num in enumerate(nums):
        value_to_index[num].append(i)

    max_run = 0
    for i, num in enumerate(nums):
        if i in value_to_index[num]:
            value_to_index[num].remove(i)
            current = num
            run_length = 1
            while True:
                current += 1
                if current in value_to_index and value_to_index[current]:
                    run_length += 1
                    value_to_index[current].remove(i)
                else:
                    break
            current = num - 1
            while True:
                current -= 1
                if current in value_to_index and value_to_index[current]:
                    run_length += 1
                    value_to_index[current].remove(i)
                else:
                    break
            max_run = max(max_run, run_length)
    return max_run
