def solve(nums):
    from collections import Counter

    if not nums:
        return 0

    count = Counter(nums)
    unique_nums = list(count.keys())
    unique_nums.sort()

    def get_longest_run():
        n = len(unique_nums)
        max_run = 0
        current_run = 1

        for i in range(1, n):
            if unique_nums[i] == unique_nums[i - 1] + 1:
                current_run += 1
                max_run = max(max_run, current_run)
            else:
                current_run = 1

        return max_run

    return get_longest_run()
```

