def solve(strs):
    def is_anagram(word1, word2):
        return sorted(word1) == sorted(word2)

    groups = []
    used = set()

    for word in strs:
        if word in used:
            continue
        group = [word]
        used.add(word)
        for other in strs:
            if other in used:
                continue
            if is_anagram(word, other):
                group.append(other)
                used.add(other)
        groups.append(group)

    return groups
```

