    count = [0] * (n + 1)
    for c in citations:
        if c <= n:
            count[c] += 1
        else:
            count[n] += 1
    h = 0
    for i in range(n, 0, -1):
        h += count[i]
        if h >= i:
            return i
    return 0
```

