from collections import defaultdict

def solve(citations):
    freq = defaultdict(int)
    for c in citations:
        freq[c] += 1

    max_citation = max(citations)
    for h in range(max_citation, -1, -1):
        count = 0
        for c in freq:
            if c >= h:
