        nums[i], nums[ptr0] = nums[ptr0], nums[i]
        nonlocal ptr0
        ptr0 += 1

    def swap2(i):
        nums[i], nums[ptr2] = nums[ptr2], nums[i]
        nonlocal ptr2
        ptr2 -= 1

    ptr0 = 0
    ptr2 = len(nums) - 1
    i = 0
    while i <= ptr2:
        if nums[i] == 0:
            swap0(i)
        elif nums[i] == 2:
            swap2(i)
        else:
            i += 1
