    def swap(i, j):
        nums[i], nums[j] = nums[j], nums[i]

    low = 0
    high = len(nums) - 1
    i = 0

    while i <= high:
        if nums[i] == 0:
            swap(low, i)
            low += 1
            i += 1
        elif nums[i] == 2:
            swap(i, high)
            high -= 1
        else:
            i += 1
