def solve(nums):
    def count_occurrences(nums):
        count = [0, 0, 0]
        for num in nums:
            count[num] += 1
        return count

    def place_zeros(count, nums):
        idx = 0
        for i in range(count[0]):
            nums[idx] = 0
            idx += 1

    def place_ones(count, nums):
        idx = count[0]
        for i in range(count[1]):
            nums[idx] = 1
            idx += 1

    def place_twos(count, nums):
        idx = count[0] + count[1]
        for i in range(count[2]):
            nums[idx] = 2
            idx += 1

    counts = count_occurrences(nums)
    place_zeros(counts, nums)
    place_ones(counts, nums)
    place_twos(counts, nums)
