def solve(nums):
    # Two pointers: one for 0s (left) and one for 2s (right)
    left, right = 0, len(nums) - 1

    # Traverse the list with a middle pointer
    while left <= right:
        if nums[left] == 0:
            left += 1
        elif nums[left] == 2:
            # Swap with the right pointer
            nums[left], nums[right] = nums[right], nums[left]
            right -= 1
        else:
            # nums[left] == 1, do nothing
            left += 1
