def solve(nums):
    def count_values(nums):
        count_0 = 0
        count_1 = 0
        count_2 = 0
        for num in nums:
            if num == 0:
                count_0 += 1
            elif num == 1:
                count_1 += 1
            else:
                count_2 += 1
        return count_0, count_1, count_2

    def fill_values(nums, count_0, count_1, count_2):
        idx = 0
        for _ in range(count_0):
            nums[idx] = 0
            idx += 1
        for _ in range(count_1):
            nums[idx] = 1
            idx += 1
        for _ in range(count_2):
            nums[idx] = 2
            idx += 1

    count_0, count_1, count_2 = count_values(nums)
    fill_values(nums, count_0, count_1, count_2)
