def solve(nums):
    n = len(nums)
    # Initialize a boolean array to track presence of numbers
    presence = [False] * (n + 1)
    for num in nums:
        if 1 <= num <= n:
            presence[num - 1] = True
    # Find the first index where presence is False
    for i in range(n):
        if not presence[i]:
            return i + 1
    return n + 1
```

