def solve(nums):
    n = len(nums)
    # Initialize a boolean array to track presence of numbers
    present = [False] * (n + 1)

    for num in nums:
        if 1 <= num <= n:
            present[num] = True

    # Find the first index where the value is False
    for i in range(1, n + 1):
        if not present[i]:
            return i
    return n + 1
```

