    count1 = {}
    for num in nums1:
        count1[num] = count1.get(num, 0) + 1

    # Count occurrences in nums2
    count2 = {}
    for num in nums2:
        count2[num] = count2.get(num, 0) + 1

    # Find the intersection with minimum counts
    result = []
    for num in count1:
        if num in count2:
            result.extend([num] * min(count1[num], count2[num]))

    return result
```

